import{_ as d,o,c as r,ag as n}from"./chunks/framework.D5hoimZQ.js";const i=JSON.parse('{"title":"预言台账 —— 2005—2020 发的帖子，2026 年开卷对答案","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/tianya/prediction-ledger.md","filePath":"topics/tianya/prediction-ledger.md"}'),s={name:"topics/tianya/prediction-ledger.md"};function a(e,t,g,u,h,q){return o(),r("div",null,[...t[0]||(t[0]=[n(`<h1 id="预言台账-——-2005—2020-发的帖子-2026-年开卷对答案" tabindex="-1">预言台账 —— 2005—2020 发的帖子，2026 年开卷对答案 <a class="header-anchor" href="#预言台账-——-2005—2020-发的帖子-2026-年开卷对答案" aria-label="Permalink to &quot;预言台账 —— 2005—2020 发的帖子，2026 年开卷对答案&quot;">​</a></h1><blockquote><p>整理日期：2026-11-06 · 材料：<code>notes/</code> 01—04 卷的「预测对照（→2026）」逐条汇总 本文件把<strong>分散在各帖末尾的检验结果</strong>汇成一张统一量表，并给出<strong>可复用的打分卡</strong>。</p></blockquote><blockquote><p>关键词：天涯神贴, 预言命中率, 可证伪性, 打分卡, 失效条件, 房价预测, 汇率预测, 点位择时, 时点错觉, 事后判定偏差, 利益分析法, 宏观预测, 通缩, 通胀, 泡沫</p></blockquote><hr><h2 id="一、总成绩-按-方向—结构—点位-三层分解" tabindex="-1">一、总成绩（按&quot;方向—结构—点位&quot;三层分解） <a class="header-anchor" href="#一、总成绩-按-方向—结构—点位-三层分解" aria-label="Permalink to &quot;一、总成绩（按&quot;方向—结构—点位&quot;三层分解）&quot;">​</a></h2><p>04 卷总览给的结论，就是本主题最重要的一句话：</p><table tabindex="0"><thead><tr><th>层</th><th>命中率</th><th>谁做到了</th><th>为什么</th></tr></thead><tbody><tr><td><strong>结构性判断</strong>（制度逻辑、人口、行业兴衰）</td><td><strong>7—8 成</strong></td><td>kkndme 的调控逻辑、老仇的通缩/巨头/人口三部曲、Kulese 的&quot;危机必放水&quot;、北京毛毛的老龄化与黄金</td><td>决策者<strong>选项集有限</strong>，约束比意愿可靠</td></tr><tr><td><strong>方向性宏观</strong>（通胀 vs 通缩、汇率区间）</td><td><strong>约 5 成</strong></td><td>通缩派赢了通胀派；汇率全军覆没</td><td>一半人注定错，且没人猜中&quot;横在 7&quot;这个最无聊的答案</td></tr><tr><td><strong>点位与择时</strong></td><td><strong>约 3 成</strong></td><td>唯一成功择时：老仇 2020-03-01 做空美股</td><td>样本里最强的那些点位，无一兑现</td></tr></tbody></table><blockquote><p>⚠️ <strong>读这张表前先认两件事</strong>：①这是<strong>事后判定</strong>，不等于事前可判；②样本只有几十帖且是<strong>被精选过的神贴</strong>，天然有幸存者偏差。它证明的是&quot;哪类判断更耐用&quot;，不是&quot;这些人很神&quot;。</p></blockquote><hr><h2 id="二、表-a-结构性判断-最耐用-7—8-成" tabindex="-1">二、表 A｜结构性判断（最耐用，7—8 成） <a class="header-anchor" href="#二、表-a-结构性判断-最耐用-7—8-成" aria-label="Permalink to &quot;二、表 A｜结构性判断（最耐用，7—8 成）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>出自</th><th>年代</th><th>判断</th><th>→2026 检验</th></tr></thead><tbody><tr><td>kkndme（01）</td><td>2010</td><td>调控真实目的是中央收权、踢出小开发商；房产税难产且会向房租转嫁</td><td><strong>准</strong>：2015—2017 暴涨、房产税落空、限购限售成主工具</td></tr><tr><td>kkndme（01）</td><td>2010</td><td>楼市若不再吸金，物价（蒜、姜、绿豆）替它吸</td><td><strong>准</strong>：调控后蒜姜暴涨</td></tr><tr><td>炒房人（01）</td><td>2010</td><td>政策—媒体五阶段剧本（揭露→表决心→夸成果→做秀要挟→托市）</td><td><strong>准</strong>：2010—2015 历轮调控反复应验</td></tr><tr><td>炒房人（01）</td><td>2010</td><td>2015—2020 人口红利结束</td><td><strong>准</strong>：2022 年人口负增长（略晚）</td></tr><tr><td>孤独的思想（01）</td><td>2005</td><td>对二手房征税越多→房源冻结→反逼人买新盘抬高新房价</td><td><strong>准</strong>：2021 二手房指导价是极端版</td></tr><tr><td>海男的故事（02）</td><td>2016</td><td>短期房价看首付/利率/政策，长期看人口；人口净流出城市绝对不碰</td><td><strong>准</strong>：环京与都市圈小城市暴跌被精准预警</td></tr><tr><td>海男的故事（02）</td><td>2016</td><td>&quot;什么时候大跌？经济危机&quot;</td><td><strong>准</strong>：2021—2026 恰是&quot;经济下行 + 温和下跌&quot;组合</td></tr><tr><td>七剑战歌之风月（03）</td><td>2018</td><td>违约潮、房企暴雷、二手房流动性陷阱</td><td><strong>准</strong>：2021 年后兑现</td></tr><tr><td>七剑战歌之风月（03）</td><td>2018</td><td>小银行出险</td><td><strong>准</strong>：2019 包商被接管</td></tr><tr><td>螺蛳大少（03）</td><td>2011</td><td>乱象整治无效、收费变形复活；风险靠展期不会消失</td><td><strong>准</strong>：2013 钢贸崩盘，风险层层延期至房企与城投</td></tr><tr><td>螺蛳大少（03）</td><td>2011</td><td>公司信贷数据失真，&quot;任何以数据为立论基础的经济分析都是扯蛋&quot;</td><td><strong>准</strong>：财政挤水分、资产质量争议不断</td></tr><tr><td>Kulese（04）</td><td>2018</td><td>凯恩斯式赎买只把问题往后拖；劳动力拐点已过；危机时必放水</td><td><strong>准</strong>：2024—2025 政策组合拳</td></tr><tr><td>Kulese（04）</td><td>2018</td><td>2440 非牛市起点</td><td><strong>准</strong>：2022—2024 二次探底证实</td></tr><tr><td>老仇乱侃（04）</td><td>2019</td><td>通缩周期来临、现金为王、降杠杆；车企手机业洗牌、巨头涌现、养老家政就业崛起</td><td><strong>准</strong>：全部兑现（作者是全合集命中率最高）</td></tr><tr><td>老仇乱侃（04）</td><td>2020</td><td>出生率跳水→从尿布到房屋的连环需求不足，人口收缩城市扩大</td><td><strong>准</strong></td></tr><tr><td>yyttff1981（03）</td><td>2018</td><td>&quot;再来一次四万亿已无可能&quot;</td><td><strong>准</strong>：2020 刺激路径完全不同</td></tr><tr><td>黄汉升1（03）</td><td>2014</td><td>金融风险向居民转移</td><td><strong>准</strong>：2015—2021 居民杠杆翻倍</td></tr><tr><td>不要二分法（03）</td><td>2019</td><td>中美对抗长期化；美国先漏&quot;工业&quot;这块板</td><td><strong>准</strong>：科技战层层加码</td></tr><tr><td>海上京叔（04）</td><td>2019</td><td>西方集体心理转熊；制造业回流停留在补贴建厂</td><td><strong>准</strong></td></tr><tr><td>北京毛毛（04）</td><td>2006</td><td>2015 年后老龄化、养老金承压</td><td><strong>准</strong>（最早源头）</td></tr></tbody></table><p><strong>结构层为什么耐用</strong>：这一层的判断对象是<strong>约束</strong>（财政依赖度、人口结构、决策者选项集），而约束的变化比意愿慢一个数量级。<strong>盯约束，不盯意志。</strong></p><hr><h2 id="三、表-b-方向性宏观-约-5-成-且几乎全是-方向对、幅度错" tabindex="-1">三、表 B｜方向性宏观（约 5 成，且几乎全是&quot;方向对、幅度错&quot;） <a class="header-anchor" href="#三、表-b-方向性宏观-约-5-成-且几乎全是-方向对、幅度错" aria-label="Permalink to &quot;三、表 B｜方向性宏观（约 5 成，且几乎全是&quot;方向对、幅度错&quot;）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>出自</th><th>年代</th><th>判断</th><th>→2026 检验</th></tr></thead><tbody><tr><td>通缩派（曼因斯坦 03 / 七剑 03 / 第三元 03 / Kulese 04）</td><td>2013—2018</td><td>从&quot;印钞—通胀&quot;切到&quot;债务—通缩&quot;；放水不再变成物价，而是变成债务滚动</td><td><strong>准</strong>（03 卷总览认定：全部帖子里最经得起检验的判断）</td></tr><tr><td>通胀派（04 卷 169/199/165）</td><td>2019</td><td>大通胀时代降临</td><td><strong>半对</strong>：全球通胀那一半中了，中国需求塌陷的那一半集体失明</td></tr><tr><td>高天无影1（04）</td><td>2019</td><td>黄金大牛市；2021—2022 全球大通胀</td><td><strong>准</strong>，金价从 1500 涨向 3000 美元上方（最硬的宏观兑现之一）</td></tr><tr><td>北京毛毛（04）</td><td>2006</td><td>长期看好黄金至 2000 美元上方</td><td><strong>准</strong>：2011 破 1900，2020 后长牛至 3000+</td></tr><tr><td>潜龙一生在渊（04）</td><td>2017</td><td>滞胀将至</td><td><strong>半对</strong>：&quot;滞&quot;一字成谶（2019—2025），&quot;胀&quot;落空</td></tr><tr><td>flp713（03）</td><td>2011</td><td>两位数 CPI 偷走财富</td><td><strong>不准</strong>：官方 CPI 长期 2% 上下，2023 年后反成通缩压力</td></tr><tr><td>flp713（03）</td><td>2011</td><td>中国还有黄金十年；房价调控后必报复性上涨</td><td><strong>准</strong>（2012—2021）</td></tr><tr><td>王海滨（03）</td><td>2009</td><td>房地产十年不能衰败；土地财政绑架地方</td><td><strong>准</strong>（2009—2021）</td></tr><tr><td>大江宁静（04）</td><td>2018</td><td>转向内需为主；限购&quot;横盘冻结&quot;期</td><td><strong>准</strong></td></tr><tr><td>大江宁静（04）</td><td>2018</td><td>中美贸易战打不起来</td><td><strong>不准</strong>：2018.07 即开打并延续成科技战</td></tr><tr><td>时代之（04）</td><td>2019</td><td>房价五年内大概率下跌</td><td><strong>准</strong>：2021 见顶后连跌数年</td></tr><tr><td>我就是ladisai（04）</td><td>2017</td><td>2023—2024 为重大转折</td><td><strong>部分准</strong>：与实际出清节点吻合，但论证依赖推背图卦辞</td></tr><tr><td>高级工程狮A（04）</td><td>2018</td><td>注册制（科创板）将重构股价；持币</td><td><strong>准</strong>：2019.07 落地；持币此后两年跑赢</td></tr><tr><td>邹艺湘（04）</td><td>2017</td><td>比亚迪销量登顶；&quot;十年回本&quot;估值铁律</td><td><strong>部分准</strong>：比亚迪登顶准；银行股 2024—25 大涨但未翻倍修复</td></tr></tbody></table><h3 id="🎯-汇率-全军覆没" tabindex="-1">🎯 汇率：全军覆没 <a class="header-anchor" href="#🎯-汇率-全军覆没" aria-label="Permalink to &quot;🎯 汇率：全军覆没&quot;">​</a></h3><table tabindex="0"><thead><tr><th>谁</th><th>怎么猜</th><th>实际</th></tr></thead><tbody><tr><td>老江南（04）</td><td>有序贬到 8</td><td>RMB 横在 7.1—7.3</td></tr><tr><td>高级工程狮A（04）</td><td>升到 6.4、热钱涌入</td><td>落空</td></tr><tr><td>样条曲线A（04）</td><td>唯一出路是大幅升值（甚至到 3）</td><td>反向：RMB 未升值</td></tr><tr><td>北望帝都（01）</td><td>人民币升到 3:1</td><td>落空</td></tr><tr><td>七剑（03）/ 第三元（03）</td><td>贬值、被动紧缩</td><td>方向对，幅度错；2020 疫情大放水反其道</td></tr></tbody></table><blockquote><p>⭐ <strong>没人猜中&quot;横在 7&quot;。</strong> —— 最无聊的答案是最常发生的答案；<strong>预测者系统性偏爱戏剧性。</strong></p></blockquote><hr><h2 id="四、表-c-点位与择时-约-3-成-打脸集中区" tabindex="-1">四、表 C｜点位与择时（约 3 成，打脸集中区） <a class="header-anchor" href="#四、表-c-点位与择时-约-3-成-打脸集中区" aria-label="Permalink to &quot;四、表 C｜点位与择时（约 3 成，打脸集中区）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>出自</th><th>年代</th><th>判断</th><th>→2026 检验</th></tr></thead><tbody><tr><td><strong>时代之（04）</strong></td><td>2019</td><td>纳指 8000—8500 是&quot;三重大顶&quot;，<strong>可做空</strong></td><td><strong>最大打脸</strong>：2021—2025 涨破 20000</td></tr><tr><td>曼因斯坦（03）</td><td>2016</td><td>美股历史大顶在一两个月内</td><td><strong>不准</strong>：随后又涨四年多</td></tr><tr><td>系统方法论（04）</td><td>2018</td><td>房产税 2020 年前开征；荐铁龙物流目标 40 元</td><td><strong>基本不准</strong>（典型荐股引流帖）</td></tr><tr><td>老江南（04）</td><td>2018</td><td>上证区间 1900—2100；GDP 6.5%</td><td><strong>偏悲观</strong>：跌破 2449 准，区间下沿未到</td></tr><tr><td>天之星（04）</td><td>2019</td><td>A 股&quot;一万点会到的&quot;</td><td><strong>不准</strong></td></tr><tr><td>第三元（03）</td><td>2013</td><td>房价 2016—2018 下跌</td><td><strong>不准</strong>：2016—17 暴涨（方向对、时点错 3 年+）</td></tr><tr><td>七剑（03）</td><td>2018</td><td>2018 年内房价崩至 2015 底</td><td><strong>不准</strong>：2018—21 还冲顶</td></tr><tr><td>曼因斯坦（03）</td><td>2016</td><td>2017 楼市全面着陆</td><td><strong>不准</strong>：一线仅短暂回调</td></tr><tr><td>kulese（03）</td><td>2015</td><td>2016 新纪元慢牛</td><td><strong>不准</strong>：2016 年初熔断</td></tr><tr><td>kkndme（04）</td><td>2010</td><td>房价以人民币计价难跌</td><td><strong>准了十年，2021 年后失效</strong></td></tr><tr><td>北望帝都（01）</td><td>2010</td><td>北京四环内 8 万</td><td><strong>半对</strong>：2020—21 触及，但&quot;任何时候买房都对&quot;成反面教材</td></tr></tbody></table><h3 id="✅-唯一成功的择时" tabindex="-1">✅ 唯一成功的择时 <a class="header-anchor" href="#✅-唯一成功的择时" aria-label="Permalink to &quot;✅ 唯一成功的择时&quot;">​</a></h3><p>| 老仇乱侃（04） | 2020-03-01 | &quot;美股再上去就是做空好时机&quot; | <strong>准</strong>：一周后熔断式崩盘 |</p><blockquote><p>连 04 卷笔记都注明：&quot;更像周期认知<strong>加运气</strong>&quot;。别把单次择时成功当能力。</p></blockquote><hr><h2 id="五、表-d-玄学与不可证伪-4-篇" tabindex="-1">五、表 D｜玄学与不可证伪（4 篇） <a class="header-anchor" href="#五、表-d-玄学与不可证伪-4-篇" aria-label="Permalink to &quot;五、表 D｜玄学与不可证伪（4 篇）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>出自</th><th>说了什么</th><th>检验</th><th>处置</th></tr></thead><tbody><tr><td>庖丁医命0（04）</td><td>未来十余年行&quot;火运&quot;→AI/数字化、文化教育、能源、军工有前景；2020 庚子年有大劫；2019.12 底预测美欧股市春节前后共振大跌</td><td><strong>三连中</strong>（AI 与军工兑现、保地产延续、2020 疫情 + 美股四次熔断），<strong>时点命中率反超多数技术派</strong></td><td>记下命中，<strong>存疑方法</strong></td></tr><tr><td>庖丁医命0（04）</td><td>衰退与高通胀交替的&quot;螺旋式下跌&quot;，多数人保不住财富</td><td><strong>部分准</strong>：次序反了（直接进通缩），&quot;多数人保不住财富&quot;应验</td><td>同上</td></tr><tr><td>小纯人（04）</td><td>灵界征文式幻想，预言&quot;人间战乱、灾荒、瘟疫即将开始&quot;</td><td><strong>不可证伪</strong></td><td>视为文学</td></tr><tr><td>我就是ladisai（04）</td><td>借推背图&quot;黑兔走入青龙穴&quot;指 2023—2024 转折</td><td><strong>部分准</strong>（节点吻合，理由不可修正）</td><td>&quot;记对了时代、算错了理由&quot;</td></tr></tbody></table><p><strong>共同处置（沿用笔记口径）：</strong> 五行/卦辞外壳<strong>无法证伪、无法修正</strong> —— 时点一错全盘皆输，方向感再好也不可复现。<strong>当认知现象记录，不当方法论采用。</strong></p><hr><h2 id="六、⭐-可证伪性打分卡-本台账的产出物" tabindex="-1">六、⭐ 可证伪性打分卡（本台账的产出物） <a class="header-anchor" href="#六、⭐-可证伪性打分卡-本台账的产出物" aria-label="Permalink to &quot;六、⭐ 可证伪性打分卡（本台账的产出物）&quot;">​</a></h2><h3 id="_6-1-读别人的预言-给四条打分" tabindex="-1">6.1 读别人的预言：给四条打分 <a class="header-anchor" href="#_6-1-读别人的预言-给四条打分" aria-label="Permalink to &quot;6.1 读别人的预言：给四条打分&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 它预测的是&quot;约束&quot;还是&quot;意志&quot;？       约束（人口/财政/选项集）→ +2 ；意志（&quot;政府一定会&quot;）→ 0</span></span>
<span class="line"><span>② 它把方向/结构/点位分开说了吗？      分开 → +2 ；混成一句 → 0</span></span>
<span class="line"><span>③ 它写明失效条件了吗？                &quot;若 X 发生则此论不成立&quot; → +3 ；只给结论 → 0</span></span>
<span class="line"><span>④ 它承认能力边界吗？                  &quot;我不知道&quot; / &quot;太草率&quot; → +2 ；&quot;准确率100%&quot; → 直接判流量生意</span></span></code></pre></div><p><strong>总分 ≥5 值得读；≤2 当娱乐；出现&quot;全知口吻&quot;直接归零，不看内容。</strong></p><p>（③是最稀缺的——02 卷里唯一&quot;全程成立&quot;的帖子，正是那句带条件的判断：<strong>&quot;除非经济危机&quot;</strong>。无条件的信仰&quot;十年不跌&quot;&quot;永远屡创新高&quot;，全错。）</p><h3 id="_6-2-写自己的判断-四条纪律" tabindex="-1">6.2 写自己的判断：四条纪律 <a class="header-anchor" href="#_6-2-写自己的判断-四条纪律" aria-label="Permalink to &quot;6.2 写自己的判断：四条纪律&quot;">​</a></h3><ol><li><strong>先写失效条件再写结论</strong>——&quot;什么情况下我错了&quot;。这一条同时补偿了幸存者偏差。</li><li><strong>分开记三层</strong>——结构（我认为机制是什么）／方向（往哪走）／点位（到哪、何时）。<strong>允许三层分开记分</strong>，别用点位失败去否定结构。</li><li><strong>警惕最大的错觉：时点错觉</strong>——见下节。</li><li><strong>声明自己的激励</strong>——&quot;我靠什么赚钱&quot;（见 <code>shengtie-formula.md</code> §4）。</li></ol><h3 id="_6-3-最容易准-vs-最容易错-04-卷总结-可直接抄" tabindex="-1">6.3 最容易准 vs 最容易错（04 卷总结，可直接抄） <a class="header-anchor" href="#_6-3-最容易准-vs-最容易错-04-卷总结-可直接抄" aria-label="Permalink to &quot;6.3 最容易准 vs 最容易错（04 卷总结，可直接抄）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>最容易准</th><th>最容易错</th></tr></thead><tbody><tr><td>从利益结构与政策约束出发的推演（决策者选项集有限）</td><td>给市场定<strong>具体点位</strong>、给汇率定<strong>终值</strong></td></tr><tr><td><strong>人口与代际长变量</strong>（周期以十年计，容错高）</td><td>把&quot;美国必衰/美元必崩&quot;当<strong>公理</strong></td></tr><tr><td>猜&quot;<strong>什么东西会消失</strong>&quot;（普惠暴富、薄利多销、卖场）比猜&quot;什么会暴涨&quot;容易</td><td>把<strong>短期货币状态当永恒</strong>（kkndme 统治了十年，在土地财政拐点处失效）</td></tr><tr><td>—</td><td>玄学模型：方向感不差，但<strong>无法修正</strong></td></tr></tbody></table><hr><h2 id="七、⭐-时点错觉-最贵的失败方式" tabindex="-1">七、⭐ 时点错觉：最贵的失败方式 <a class="header-anchor" href="#七、⭐-时点错觉-最贵的失败方式" aria-label="Permalink to &quot;七、⭐ 时点错觉：最贵的失败方式&quot;">​</a></h2><p>这批帖子里最反复出现的模式，<strong>不是&quot;错&quot;，而是&quot;早&quot;</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>七剑（2018）→ 说要崩，实际 2021 崩      —— 早 3 年</span></span>
<span class="line"><span>曼因斯坦（2016）→ 说 2017 全面着陆，实际 2021 —— 早 4 年</span></span>
<span class="line"><span>kulese（2015）→ 说 2016 新纪元，实际熔断 —— 早 1 年</span></span>
<span class="line"><span>69 帖（2017）→ 说&quot;没买房的是幸运的&quot;，当年错、2026 对 —— 早 3 年</span></span>
<span class="line"><span>第三元（2013）→ 说房价 2016—2018 跌，实际 2016—17 暴涨 —— 早 3 年</span></span></code></pre></div><p><strong>为什么这比&quot;错&quot;更贵</strong>：方向对的人<strong>照做了</strong>——踏空反弹、离场、做空。03 卷原话：&quot;趋势对、时点错，<strong>照做会在黎明前离场</strong>。&quot;</p><p><strong>防御办法只有一个</strong>：把&quot;方向&quot;与&quot;节奏&quot;分账户管理——方向可以用杠杆/配置表达，<strong>节奏必须靠现金流和期限撑住</strong>（02 卷 46 帖&quot;多大能力办多大事&quot;、44 帖&quot;不知道这轮周期处在少年还是中年&quot;）。</p><hr><h2 id="八、一句话收口" tabindex="-1">八、一句话收口 <a class="header-anchor" href="#八、一句话收口" aria-label="Permalink to &quot;八、一句话收口&quot;">​</a></h2><blockquote><p>预测的核心竞争力不是模型，而是对&quot;<strong>谁在决策、他怕什么</strong>&quot;的理解；<strong>凡从利益与人出发的判断大多活到了 2026，凡从情绪与信仰出发的断言，大多留在了发帖那年。</strong>（04 卷原话）</p></blockquote><hr><h2 id="九、接口" tabindex="-1">九、接口 <a class="header-anchor" href="#九、接口" aria-label="Permalink to &quot;九、接口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>关联</th><th>连接点</th></tr></thead><tbody><tr><td><code>tianya/index.md</code></td><td>十卷地图、六件工具、使用纪律</td></tr><tr><td><code>tianya/shengtie-formula.md</code></td><td>配方 1（利益分析推演）的可信度从哪来</td></tr><tr><td><code>economic-cycles/</code></td><td>通缩切换、资产负债表衰退的理论面</td></tr><tr><td><code>real-estate/</code></td><td>判断方法的<strong>前瞻版</strong>（证据硬度阶梯）vs 本台账的<strong>复盘版</strong></td></tr><tr><td><code>philosophy/</code></td><td>归纳问题、可证伪性、&quot;这一次不一样&quot;的失效条件</td></tr><tr><td><code>ai-system-architecture/</code></td><td><strong>待办</strong>：用 §6.1 打分卡试评今天的 AI 主张（可作一次实证练习）</td></tr><tr><td><code>source-verification</code>（skill）</td><td>同一套&quot;看谁发的 + 能否独立验证 + 失真在哪层&quot;</td></tr></tbody></table><hr><p><em>核心原则：<strong>这批帖子最大的用处不是让你相信什么，而是让你看到——同一批聪明人用同一套方法，在同一个方向上一半对一半错，而错的全都错在&quot;什么时候&quot;。</strong></em></p>`,52)])])}const c=d(s,[["render",a]]);export{i as __pageData,c as default};
